"kind": "propose",
"summary": "The container's memory limit is too low, causing OOM kills. Increase the memory limit to prevent crashes.",
"hypotheses": [
  {
    "root_cause_class": "memory_limit_too_low",
    "summary": "The container's peak memory usage (59.76Mi) reached 95% of its limit (60Mi), leading to OOM kills.",
    "supporting": ["ev-container_memory", "ev-pod_states"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "catalog",
    "uid": "uid-deployment-catalog"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "memory": "90Mi"
        }
      }
    }
  },
  "expected_effect": "The memory limit for the 'app' container will be increased to 90Mi, preventing OOM kills.",
  "rationale": "The container's peak memory usage (59.76Mi) reached 95% of its limit (60Mi), leading to OOM kills. Increasing the limit to 90Mi provides a buffer to prevent such issues.",
  "cited_evidence_ids": ["ev-container_memory", "ev-pod_states"],
  "cited_predicates": ["oom_killed_current_revision", "memory_at_limit_before_kill", "memory_data_available"]
}
}
